CREATE VIEW [dbo].[vwD365MemberTransactionsSettlementsWIP]
 AS
SELECT DISTINCT CT.ACCOUNTNUM,S.VOUCHER,S.LASTSETTLEVOUCHER,LASTSETTLEDATE,AMOUNTCUR,S.Currency,CT.PAYMREFERENCE,CT.PAYMMODE AS PaymentType
FROM FO.vwCustTrans CT
INNER JOIN dbo.vwD365MemberTransactionsWIP S
		ON S.ContactNumber = CT.ACCOUNTNUM
WHERE S.VOUCHER = CT.LASTSETTLEVOUCHER
